# 6-ingilizce-14 görsel modülü

GORSELLER = {'b1': '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">THEME 3: PERSONAL LIFE — BODY PARTS &amp; PHYSICAL APPEARANCE</text>\n  <rect x="20" y="48" width="320" height="190" rx="8" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="180" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Target Body Parts (Vücut Bölümleri)</text>\n  <text x="180" y="100" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e3a8a">knee (diz) · ankle (ayak bileği)</text>\n  <text x="180" y="128" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e3a8a">stomach (mide / karın) · heart (kalp)</text>\n  <text x="180" y="156" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e3a8a">back (sırt / bel) · skin (cilt / deri)</text>\n  <text x="180" y="184" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e3a8a">shoulder (omuz) · neck (boyun) · wrist (bilek)</text>\n  <text x="180" y="214" text-anchor="middle" font-size="11" fill="#475569">Protect your skin and keep your heart healthy!</text>\n  <rect x="360" y="48" width="320" height="190" rx="8" fill="#f0fdf4" stroke="#22c55e" stroke-width="1.5"/>\n  <text x="520" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Physical Appearance (Dış Görünüş)</text>\n  <text x="520" y="100" text-anchor="middle" font-size="12" font-weight="bold" fill="#14532d">What does he / she look like?</text>\n  <text x="520" y="126" text-anchor="middle" font-size="11" fill="#334155">Height: tall · medium-height · short</text>\n  <text x="520" y="150" text-anchor="middle" font-size="11" fill="#334155">Build: slim / thin · well-built · plump</text>\n  <text x="520" y="174" text-anchor="middle" font-size="11" fill="#334155">Hair: straight · wavy · curly · fair / dark</text>\n  <text x="520" y="198" text-anchor="middle" font-size="11" fill="#334155">Eyes &amp; Skin: hazel eyes · fair / dark skin</text>\n  <text x="520" y="220" text-anchor="middle" font-size="11" font-weight="bold" fill="#15803d">is / has got: She is tall and has got wavy hair.</text>\n</svg>', '1': '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">THEME 3: PERSONAL LIFE — BODY PARTS &amp; PHYSICAL APPEARANCE</text>\n  <rect x="20" y="48" width="320" height="190" rx="8" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="180" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Target Body Parts (Vücut Bölümleri)</text>\n  <text x="180" y="100" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e3a8a">knee (diz) · ankle (ayak bileği)</text>\n  <text x="180" y="128" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e3a8a">stomach (mide / karın) · heart (kalp)</text>\n  <text x="180" y="156" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e3a8a">back (sırt / bel) · skin (cilt / deri)</text>\n  <text x="180" y="184" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e3a8a">shoulder (omuz) · neck (boyun) · wrist (bilek)</text>\n  <text x="180" y="214" text-anchor="middle" font-size="11" fill="#475569">Protect your skin and keep your heart healthy!</text>\n  <rect x="360" y="48" width="320" height="190" rx="8" fill="#f0fdf4" stroke="#22c55e" stroke-width="1.5"/>\n  <text x="520" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Physical Appearance (Dış Görünüş)</text>\n  <text x="520" y="100" text-anchor="middle" font-size="12" font-weight="bold" fill="#14532d">What does he / she look like?</text>\n  <text x="520" y="126" text-anchor="middle" font-size="11" fill="#334155">Height: tall · medium-height · short</text>\n  <text x="520" y="150" text-anchor="middle" font-size="11" fill="#334155">Build: slim / thin · well-built · plump</text>\n  <text x="520" y="174" text-anchor="middle" font-size="11" fill="#334155">Hair: straight · wavy · curly · fair / dark</text>\n  <text x="520" y="198" text-anchor="middle" font-size="11" fill="#334155">Eyes &amp; Skin: hazel eyes · fair / dark skin</text>\n  <text x="520" y="220" text-anchor="middle" font-size="11" font-weight="bold" fill="#15803d">is / has got: She is tall and has got wavy hair.</text>\n</svg>', 'b2': '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">TARGET CLOTHES, SPORTSWEAR &amp; ACCESSORIES</text>\n  <rect x="20" y="48" width="320" height="190" rx="8" fill="#fefce8" stroke="#eab308" stroke-width="1.5"/>\n  <text x="180" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">Clothes &amp; Sportswear (Kıyafetler)</text>\n  <text x="180" y="102" text-anchor="middle" font-size="12" font-weight="bold" fill="#854d0e">trainers (spor ayakkabı) · kit (spor forması)</text>\n  <text x="180" y="130" text-anchor="middle" font-size="12" font-weight="bold" fill="#854d0e">swimsuit (mayo) · tights (tayt / külotlu çorap)</text>\n  <text x="180" y="158" text-anchor="middle" font-size="12" font-weight="bold" fill="#854d0e">pocket (cep) · hoodie · tracksuit · coat</text>\n  <text x="180" y="186" text-anchor="middle" font-size="11" fill="#475569">Plural nouns: trainers, tights, trousers, jeans</text>\n  <text x="180" y="212" text-anchor="middle" font-size="11" font-weight="bold" fill="#a16207">are used with plural verbs (These trainers are new).</text>\n  <rect x="360" y="48" width="320" height="190" rx="8" fill="#fdf2f8" stroke="#ec4899" stroke-width="1.5"/>\n  <text x="520" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#be185d">Jewellery &amp; Personal Items (Takı ve Eşya)</text>\n  <text x="520" y="102" text-anchor="middle" font-size="12" font-weight="bold" fill="#9d174d">jewellery (mücevher / takı - uncountable)</text>\n  <text x="520" y="130" text-anchor="middle" font-size="12" font-weight="bold" fill="#9d174d">necklace (kolye) · bracelet (bileklik)</text>\n  <text x="520" y="158" text-anchor="middle" font-size="12" font-weight="bold" fill="#9d174d">chain (zincir) · ring (yüzük) · earrings (küpe)</text>\n  <text x="520" y="186" text-anchor="middle" font-size="12" font-weight="bold" fill="#9d174d">wallet (cüzdan) · purse (bozuk para/el cüzdanı)</text>\n  <text x="520" y="214" text-anchor="middle" font-size="11" fill="#475569">He puts his wallet in his jacket pocket.</text>\n</svg>', '2': '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">TARGET CLOTHES, SPORTSWEAR &amp; ACCESSORIES</text>\n  <rect x="20" y="48" width="320" height="190" rx="8" fill="#fefce8" stroke="#eab308" stroke-width="1.5"/>\n  <text x="180" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">Clothes &amp; Sportswear (Kıyafetler)</text>\n  <text x="180" y="102" text-anchor="middle" font-size="12" font-weight="bold" fill="#854d0e">trainers (spor ayakkabı) · kit (spor forması)</text>\n  <text x="180" y="130" text-anchor="middle" font-size="12" font-weight="bold" fill="#854d0e">swimsuit (mayo) · tights (tayt / külotlu çorap)</text>\n  <text x="180" y="158" text-anchor="middle" font-size="12" font-weight="bold" fill="#854d0e">pocket (cep) · hoodie · tracksuit · coat</text>\n  <text x="180" y="186" text-anchor="middle" font-size="11" fill="#475569">Plural nouns: trainers, tights, trousers, jeans</text>\n  <text x="180" y="212" text-anchor="middle" font-size="11" font-weight="bold" fill="#a16207">are used with plural verbs (These trainers are new).</text>\n  <rect x="360" y="48" width="320" height="190" rx="8" fill="#fdf2f8" stroke="#ec4899" stroke-width="1.5"/>\n  <text x="520" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#be185d">Jewellery &amp; Personal Items (Takı ve Eşya)</text>\n  <text x="520" y="102" text-anchor="middle" font-size="12" font-weight="bold" fill="#9d174d">jewellery (mücevher / takı - uncountable)</text>\n  <text x="520" y="130" text-anchor="middle" font-size="12" font-weight="bold" fill="#9d174d">necklace (kolye) · bracelet (bileklik)</text>\n  <text x="520" y="158" text-anchor="middle" font-size="12" font-weight="bold" fill="#9d174d">chain (zincir) · ring (yüzük) · earrings (küpe)</text>\n  <text x="520" y="186" text-anchor="middle" font-size="12" font-weight="bold" fill="#9d174d">wallet (cüzdan) · purse (bozuk para/el cüzdanı)</text>\n  <text x="520" y="214" text-anchor="middle" font-size="11" fill="#475569">He puts his wallet in his jacket pocket.</text>\n</svg>', 'b3': '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">PERSONALITY AND CHARACTER TRAITS (KİŞİLİK VE KARAKTER)</text>\n  <rect x="20" y="48" width="660" height="44" rx="8" fill="#1e293b"/>\n  <text x="350" y="75" text-anchor="middle" font-size="13" font-weight="bold" fill="#fde047">Question: «What is he / she like?» -&gt; Answer: «He is honest, generous and cheerful.»</text>\n  <rect x="20" y="104" width="210" height="134" rx="8" fill="#ecfdf5" stroke="#10b981" stroke-width="1.5"/>\n  <text x="125" y="128" text-anchor="middle" font-size="12" font-weight="bold" fill="#047857">Social &amp; Kind Traits</text>\n  <text x="125" y="152" text-anchor="middle" font-size="11" fill="#334155">outgoing (dışa dönük)</text>\n  <text x="125" y="172" text-anchor="middle" font-size="11" fill="#334155">generous (cömert) · polite (kibar)</text>\n  <text x="125" y="192" text-anchor="middle" font-size="11" fill="#334155">helpful (yardımsever)</text>\n  <text x="125" y="212" text-anchor="middle" font-size="11" fill="#334155">cheerful (neşeli) · friendly</text>\n  <rect x="245" y="104" width="210" height="134" rx="8" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="350" y="128" text-anchor="middle" font-size="12" font-weight="bold" fill="#1d4ed8">Reliable &amp; Mindful Traits</text>\n  <text x="350" y="152" text-anchor="middle" font-size="11" fill="#334155">honest (dürüst) · reliable (güvenilir)</text>\n  <text x="350" y="172" text-anchor="middle" font-size="11" fill="#334155">hardworking (çalışkan)</text>\n  <text x="350" y="192" text-anchor="middle" font-size="11" fill="#334155">patient (sabırlı) · punctual (dakik)</text>\n  <text x="350" y="212" text-anchor="middle" font-size="11" fill="#334155">creative (yaratıcı) · calm (sakin)</text>\n  <rect x="470" y="104" width="210" height="134" rx="8" fill="#fff1f2" stroke="#f43f5e" stroke-width="1.5"/>\n  <text x="575" y="128" text-anchor="middle" font-size="12" font-weight="bold" fill="#be123c">Opposite / Contrast Traits</text>\n  <text x="575" y="152" text-anchor="middle" font-size="11" fill="#334155">shy (utangaç) &lt;-&gt; outgoing</text>\n  <text x="575" y="172" text-anchor="middle" font-size="11" fill="#334155">selfish (bencil) &lt;-&gt; generous</text>\n  <text x="575" y="192" text-anchor="middle" font-size="11" fill="#334155">stubborn (inatçı) &lt;-&gt; easy-going</text>\n  <text x="575" y="212" text-anchor="middle" font-size="11" fill="#334155">forgetful (unutkan) · lazy (tembel)</text>\n</svg>', '3': '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">PERSONALITY AND CHARACTER TRAITS (KİŞİLİK VE KARAKTER)</text>\n  <rect x="20" y="48" width="660" height="44" rx="8" fill="#1e293b"/>\n  <text x="350" y="75" text-anchor="middle" font-size="13" font-weight="bold" fill="#fde047">Question: «What is he / she like?» -&gt; Answer: «He is honest, generous and cheerful.»</text>\n  <rect x="20" y="104" width="210" height="134" rx="8" fill="#ecfdf5" stroke="#10b981" stroke-width="1.5"/>\n  <text x="125" y="128" text-anchor="middle" font-size="12" font-weight="bold" fill="#047857">Social &amp; Kind Traits</text>\n  <text x="125" y="152" text-anchor="middle" font-size="11" fill="#334155">outgoing (dışa dönük)</text>\n  <text x="125" y="172" text-anchor="middle" font-size="11" fill="#334155">generous (cömert) · polite (kibar)</text>\n  <text x="125" y="192" text-anchor="middle" font-size="11" fill="#334155">helpful (yardımsever)</text>\n  <text x="125" y="212" text-anchor="middle" font-size="11" fill="#334155">cheerful (neşeli) · friendly</text>\n  <rect x="245" y="104" width="210" height="134" rx="8" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="350" y="128" text-anchor="middle" font-size="12" font-weight="bold" fill="#1d4ed8">Reliable &amp; Mindful Traits</text>\n  <text x="350" y="152" text-anchor="middle" font-size="11" fill="#334155">honest (dürüst) · reliable (güvenilir)</text>\n  <text x="350" y="172" text-anchor="middle" font-size="11" fill="#334155">hardworking (çalışkan)</text>\n  <text x="350" y="192" text-anchor="middle" font-size="11" fill="#334155">patient (sabırlı) · punctual (dakik)</text>\n  <text x="350" y="212" text-anchor="middle" font-size="11" fill="#334155">creative (yaratıcı) · calm (sakin)</text>\n  <rect x="470" y="104" width="210" height="134" rx="8" fill="#fff1f2" stroke="#f43f5e" stroke-width="1.5"/>\n  <text x="575" y="128" text-anchor="middle" font-size="12" font-weight="bold" fill="#be123c">Opposite / Contrast Traits</text>\n  <text x="575" y="152" text-anchor="middle" font-size="11" fill="#334155">shy (utangaç) &lt;-&gt; outgoing</text>\n  <text x="575" y="172" text-anchor="middle" font-size="11" fill="#334155">selfish (bencil) &lt;-&gt; generous</text>\n  <text x="575" y="192" text-anchor="middle" font-size="11" fill="#334155">stubborn (inatçı) &lt;-&gt; easy-going</text>\n  <text x="575" y="212" text-anchor="middle" font-size="11" fill="#334155">forgetful (unutkan) · lazy (tembel)</text>\n</svg>', 'b4': '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">PRESENT SIMPLE VS. PRESENT CONTINUOUS IN PERSONAL LIFE</text>\n  <rect x="20" y="48" width="320" height="190" rx="8" fill="#eff6ff" stroke="#2563eb" stroke-width="1.5"/>\n  <text x="180" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Present Simple (Genel Alışkanlık ve Stil)</text>\n  <text x="180" y="98" text-anchor="middle" font-size="11" font-weight="bold" fill="#1e3a8a">I / You / We / They + V1 · He / She / It + V-s</text>\n  <text x="180" y="124" text-anchor="middle" font-size="11" fill="#334155">usually, always, often, every day, at weekends</text>\n  <text x="180" y="152" text-anchor="middle" font-size="11" font-weight="bold" fill="#0f172a">«Mert usually wears a school uniform</text>\n  <text x="180" y="170" text-anchor="middle" font-size="11" font-weight="bold" fill="#0f172a">and carries his wallet in his pocket.»</text>\n  <text x="180" y="204" text-anchor="middle" font-size="11" fill="#475569">Kalıcı özellikler ve günlük giyim alışkanlıkları</text>\n  <rect x="360" y="48" width="320" height="190" rx="8" fill="#f0fdf4" stroke="#16a34a" stroke-width="1.5"/>\n  <text x="520" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Present Continuous (Şu Anki Giyim ve Eylem)</text>\n  <text x="520" y="98" text-anchor="middle" font-size="11" font-weight="bold" fill="#14532d">am / is / are + V-ing</text>\n  <text x="520" y="124" text-anchor="middle" font-size="11" fill="#334155">now, right now, at the moment, today, look!</text>\n  <text x="520" y="152" text-anchor="middle" font-size="11" font-weight="bold" fill="#0f172a">«Today is Saturday, so Mert is wearing</text>\n  <text x="520" y="170" text-anchor="middle" font-size="11" font-weight="bold" fill="#0f172a">his sports kit and blue trainers now.»</text>\n  <text x="520" y="204" text-anchor="middle" font-size="11" fill="#475569">Konuşma anında giyilen kıyafet ve yapılan iş</text>\n</svg>', '4': '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">PRESENT SIMPLE VS. PRESENT CONTINUOUS IN PERSONAL LIFE</text>\n  <rect x="20" y="48" width="320" height="190" rx="8" fill="#eff6ff" stroke="#2563eb" stroke-width="1.5"/>\n  <text x="180" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Present Simple (Genel Alışkanlık ve Stil)</text>\n  <text x="180" y="98" text-anchor="middle" font-size="11" font-weight="bold" fill="#1e3a8a">I / You / We / They + V1 · He / She / It + V-s</text>\n  <text x="180" y="124" text-anchor="middle" font-size="11" fill="#334155">usually, always, often, every day, at weekends</text>\n  <text x="180" y="152" text-anchor="middle" font-size="11" font-weight="bold" fill="#0f172a">«Mert usually wears a school uniform</text>\n  <text x="180" y="170" text-anchor="middle" font-size="11" font-weight="bold" fill="#0f172a">and carries his wallet in his pocket.»</text>\n  <text x="180" y="204" text-anchor="middle" font-size="11" fill="#475569">Kalıcı özellikler ve günlük giyim alışkanlıkları</text>\n  <rect x="360" y="48" width="320" height="190" rx="8" fill="#f0fdf4" stroke="#16a34a" stroke-width="1.5"/>\n  <text x="520" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Present Continuous (Şu Anki Giyim ve Eylem)</text>\n  <text x="520" y="98" text-anchor="middle" font-size="11" font-weight="bold" fill="#14532d">am / is / are + V-ing</text>\n  <text x="520" y="124" text-anchor="middle" font-size="11" fill="#334155">now, right now, at the moment, today, look!</text>\n  <text x="520" y="152" text-anchor="middle" font-size="11" font-weight="bold" fill="#0f172a">«Today is Saturday, so Mert is wearing</text>\n  <text x="520" y="170" text-anchor="middle" font-size="11" font-weight="bold" fill="#0f172a">his sports kit and blue trainers now.»</text>\n  <text x="520" y="204" text-anchor="middle" font-size="11" fill="#475569">Konuşma anında giyilen kıyafet ve yapılan iş</text>\n</svg>', 'b5': '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">POSSESSIVE (\'S) AND «WHOSE ...?» FOR BELONGINGS</text>\n  <rect x="20" y="48" width="320" height="190" rx="8" fill="#faf5ff" stroke="#9333ea" stroke-width="1.5"/>\n  <text x="180" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#7e22ce">Singular Inquiry (Tekil Eşya)</text>\n  <text x="180" y="102" text-anchor="middle" font-size="12" font-weight="bold" fill="#581c87">Whose necklace / wallet is this?</text>\n  <text x="180" y="128" text-anchor="middle" font-size="12" font-weight="bold" fill="#15803d">It is Selin\'s necklace. (Selin\'in kolyesi)</text>\n  <text x="180" y="152" text-anchor="middle" font-size="12" fill="#334155">It is her necklace. / It is hers.</text>\n  <text x="180" y="184" text-anchor="middle" font-size="11" fill="#475569">bracelet, chain, purse, swimsuit, kit</text>\n  <text x="180" y="208" text-anchor="middle" font-size="11" font-weight="bold" fill="#7e22ce">Singular Noun + \'s (Ahmet\'s sports kit)</text>\n  <rect x="360" y="48" width="320" height="190" rx="8" fill="#fff7ed" stroke="#ea580c" stroke-width="1.5"/>\n  <text x="520" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#c2410c">Plural Inquiry (Çoğul Eşya)</text>\n  <text x="520" y="102" text-anchor="middle" font-size="12" font-weight="bold" fill="#9a3412">Whose trainers / tights are these?</text>\n  <text x="520" y="128" text-anchor="middle" font-size="12" font-weight="bold" fill="#15803d">They are my brother\'s trainers.</text>\n  <text x="520" y="152" text-anchor="middle" font-size="12" fill="#334155">They are his trainers. / They are his.</text>\n  <text x="520" y="184" text-anchor="middle" font-size="11" fill="#475569">Regular Plural + s\' (The players\' kits)</text>\n  <text x="520" y="208" text-anchor="middle" font-size="11" font-weight="bold" fill="#c2410c">Irregular Plural + \'s (The children\'s bags)</text>\n</svg>', '5': '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">POSSESSIVE (\'S) AND «WHOSE ...?» FOR BELONGINGS</text>\n  <rect x="20" y="48" width="320" height="190" rx="8" fill="#faf5ff" stroke="#9333ea" stroke-width="1.5"/>\n  <text x="180" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#7e22ce">Singular Inquiry (Tekil Eşya)</text>\n  <text x="180" y="102" text-anchor="middle" font-size="12" font-weight="bold" fill="#581c87">Whose necklace / wallet is this?</text>\n  <text x="180" y="128" text-anchor="middle" font-size="12" font-weight="bold" fill="#15803d">It is Selin\'s necklace. (Selin\'in kolyesi)</text>\n  <text x="180" y="152" text-anchor="middle" font-size="12" fill="#334155">It is her necklace. / It is hers.</text>\n  <text x="180" y="184" text-anchor="middle" font-size="11" fill="#475569">bracelet, chain, purse, swimsuit, kit</text>\n  <text x="180" y="208" text-anchor="middle" font-size="11" font-weight="bold" fill="#7e22ce">Singular Noun + \'s (Ahmet\'s sports kit)</text>\n  <rect x="360" y="48" width="320" height="190" rx="8" fill="#fff7ed" stroke="#ea580c" stroke-width="1.5"/>\n  <text x="520" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#c2410c">Plural Inquiry (Çoğul Eşya)</text>\n  <text x="520" y="102" text-anchor="middle" font-size="12" font-weight="bold" fill="#9a3412">Whose trainers / tights are these?</text>\n  <text x="520" y="128" text-anchor="middle" font-size="12" font-weight="bold" fill="#15803d">They are my brother\'s trainers.</text>\n  <text x="520" y="152" text-anchor="middle" font-size="12" fill="#334155">They are his trainers. / They are his.</text>\n  <text x="520" y="184" text-anchor="middle" font-size="11" fill="#475569">Regular Plural + s\' (The players\' kits)</text>\n  <text x="520" y="208" text-anchor="middle" font-size="11" font-weight="bold" fill="#c2410c">Irregular Plural + \'s (The children\'s bags)</text>\n</svg>', 'b6': '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">COMPARING APPEARANCE &amp; PERSONALITY (COMPARATIVE ADJECTIVES)</text>\n  <rect x="20" y="48" width="210" height="190" rx="8" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="125" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">1. Short Adjectives (+er)</text>\n  <text x="125" y="102" text-anchor="middle" font-size="11" font-weight="bold" fill="#1e3a8a">tall -&gt; taller than</text>\n  <text x="125" y="124" text-anchor="middle" font-size="11" font-weight="bold" fill="#1e3a8a">short -&gt; shorter than</text>\n  <text x="125" y="146" text-anchor="middle" font-size="11" font-weight="bold" fill="#1e3a8a">slim -&gt; slimmer than</text>\n  <text x="125" y="168" text-anchor="middle" font-size="11" font-weight="bold" fill="#1e3a8a">shy -&gt; shyer / shier than</text>\n  <text x="125" y="196" text-anchor="middle" font-size="11" fill="#475569">happy -&gt; happier than</text>\n  <rect x="245" y="48" width="210" height="190" rx="8" fill="#f0fdf4" stroke="#22c55e" stroke-width="1.5"/>\n  <text x="350" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">2. Long Adjectives (more)</text>\n  <text x="350" y="102" text-anchor="middle" font-size="11" font-weight="bold" fill="#14532d">outgoing -&gt; more outgoing</text>\n  <text x="350" y="124" text-anchor="middle" font-size="11" font-weight="bold" fill="#14532d">generous -&gt; more generous</text>\n  <text x="350" y="146" text-anchor="middle" font-size="11" font-weight="bold" fill="#14532d">cheerful -&gt; more cheerful</text>\n  <text x="350" y="168" text-anchor="middle" font-size="11" font-weight="bold" fill="#14532d">hardworking -&gt; more hardworking</text>\n  <text x="350" y="196" text-anchor="middle" font-size="11" fill="#475569">comfortable -&gt; more comfortable</text>\n  <rect x="470" y="48" width="210" height="190" rx="8" fill="#fefce8" stroke="#eab308" stroke-width="1.5"/>\n  <text x="575" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">3. Irregular Forms</text>\n  <text x="575" y="104" text-anchor="middle" font-size="12" font-weight="bold" fill="#854d0e">good -&gt; better than</text>\n  <text x="575" y="132" text-anchor="middle" font-size="12" font-weight="bold" fill="#854d0e">bad -&gt; worse than</text>\n  <text x="575" y="160" text-anchor="middle" font-size="12" font-weight="bold" fill="#854d0e">far -&gt; farther / further</text>\n  <text x="575" y="194" text-anchor="middle" font-size="11" fill="#334155">Trainers are better than boots</text>\n  <text x="575" y="212" text-anchor="middle" font-size="11" fill="#334155">for running in the sports hall.</text>\n</svg>', '6': '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">COMPARING APPEARANCE &amp; PERSONALITY (COMPARATIVE ADJECTIVES)</text>\n  <rect x="20" y="48" width="210" height="190" rx="8" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="125" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">1. Short Adjectives (+er)</text>\n  <text x="125" y="102" text-anchor="middle" font-size="11" font-weight="bold" fill="#1e3a8a">tall -&gt; taller than</text>\n  <text x="125" y="124" text-anchor="middle" font-size="11" font-weight="bold" fill="#1e3a8a">short -&gt; shorter than</text>\n  <text x="125" y="146" text-anchor="middle" font-size="11" font-weight="bold" fill="#1e3a8a">slim -&gt; slimmer than</text>\n  <text x="125" y="168" text-anchor="middle" font-size="11" font-weight="bold" fill="#1e3a8a">shy -&gt; shyer / shier than</text>\n  <text x="125" y="196" text-anchor="middle" font-size="11" fill="#475569">happy -&gt; happier than</text>\n  <rect x="245" y="48" width="210" height="190" rx="8" fill="#f0fdf4" stroke="#22c55e" stroke-width="1.5"/>\n  <text x="350" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">2. Long Adjectives (more)</text>\n  <text x="350" y="102" text-anchor="middle" font-size="11" font-weight="bold" fill="#14532d">outgoing -&gt; more outgoing</text>\n  <text x="350" y="124" text-anchor="middle" font-size="11" font-weight="bold" fill="#14532d">generous -&gt; more generous</text>\n  <text x="350" y="146" text-anchor="middle" font-size="11" font-weight="bold" fill="#14532d">cheerful -&gt; more cheerful</text>\n  <text x="350" y="168" text-anchor="middle" font-size="11" font-weight="bold" fill="#14532d">hardworking -&gt; more hardworking</text>\n  <text x="350" y="196" text-anchor="middle" font-size="11" fill="#475569">comfortable -&gt; more comfortable</text>\n  <rect x="470" y="48" width="210" height="190" rx="8" fill="#fefce8" stroke="#eab308" stroke-width="1.5"/>\n  <text x="575" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">3. Irregular Forms</text>\n  <text x="575" y="104" text-anchor="middle" font-size="12" font-weight="bold" fill="#854d0e">good -&gt; better than</text>\n  <text x="575" y="132" text-anchor="middle" font-size="12" font-weight="bold" fill="#854d0e">bad -&gt; worse than</text>\n  <text x="575" y="160" text-anchor="middle" font-size="12" font-weight="bold" fill="#854d0e">far -&gt; farther / further</text>\n  <text x="575" y="194" text-anchor="middle" font-size="11" fill="#334155">Trainers are better than boots</text>\n  <text x="575" y="212" text-anchor="middle" font-size="11" fill="#334155">for running in the sports hall.</text>\n</svg>'}

def uygula(v):
    for idx, b in enumerate(v.get('bolumler', []), 1):
        svg = GORSELLER.get(f'b{idx}') or GORSELLER.get(str(idx))
        if svg:
            b['gorsel'] = svg
    return v
